product.price = 139000
product.category = "Phones"
const describe = (p) => `${p.name}: ₦${p.price.toLocaleString("en-NG")}`
const totalStock = (inventory) => Object.values(inventory).reduce((a, b) => a + b, 0)
function cheapest(products) {
  let best = products[0]
  for (const p of products) if (p.price < best.price) best = p
  return best.name
}
function countBy(items, key) {
  const counts = {}
  for (const item of items) counts[item[key]] = (counts[item[key]] ?? 0) + 1
  return counts
}
